    private fun openTelegram(): Boolean {
        return try {
            val ctx = getCtx() ?: return false
            val intent = android.content.Intent(
                android.content.Intent.ACTION_VIEW,
                android.net.Uri.parse(telegramUrl)
            ).apply { addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK) }
            ctx.startActivity(intent)
            true
        } catch (_: Exception) { false }
    }

    private fun telegramCard(): SearchResponse =
        newMovieSearchResponse(
            telegramTitle,
            telegramUrl,
            TvType.Others
        ) { this.posterUrl = telegramPoster }

    private fun withTelegram(basePlot: String?): String {
        val clean = basePlot?.trim().orEmpty()
        return if (clean.isBlank()) telegramPlotLine
        else "$telegramPlotLine\n\n$clean"
    }
