        private val TITLE_SELECTOR: String? = "div.flex div.w-full div.flex a.font-normal h2.font-semibold"

        private const val POSTER_SELECTOR = "div.flex div.relative a.flex div.image img.poster"
        private val POSTER_ATTRS = listOf("src", "data-src").distinct()

        private val DETAIL_TITLE_SELECTOR: String? = "h2.25"

        private const val DETAIL_LINKS_SELECTOR = "a[href]"

        private const val DETAIL_POSTER_SELECTOR = "[class*=poster] img, .page-body img, .video-img img"

        private val DETAIL_HREF_HINTS = listOf("/movie/")

        // external hosts seen linking to playable pages on this site
        private val STREAM_HOSTS = listOf("developer.themoviedb.org", "status.themoviedb.org", "spidermanbrandnewday.movie", "residentevil.movie")

        // used only when STREAM_HOSTS is empty: keep external links that
        // look stream-ish by label or URL
        private val STREAM_HINT_RE = Regex(
            """watch|stream|embed|download|play|player|online|/video/|720|1080|480|2160|4k""",
            RegexOption.IGNORE_CASE
        )

        // hrefs that are never detail pages
        private val SKIP_HREF_REGEX = Regex(
            """/category/|/tag/|/tags/|/page/\d|/author/|/feed|\.xml|disclaimer|privacy|terms|about|contact|how-to-download|request-a-movie|join-our-group|dmca|whatsapp\.com|telegram|t\.me|facebook\.com|twitter\.com|instagram\.com|reddit\.com|discord\.gg|javascript:|^#|^mailto:|^tel:""",
            RegexOption.IGNORE_CASE
        )

        private val SERIES_KEYWORDS = listOf("Season", "Series", "Episode", "Episodes")
    }
